a.sh.text:
#!/bin/sh
read in
case "$in" in
  *127.0.0.1*)
    echo "$1 a $in" >> @WS@/helper.log
    echo '{"headers":{"Authorization":["Bearer a"]}}'
    ;;
  *) echo '{}' ;;
esac

